chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === 'PING') {
    sendResponse({ ok: true });
    return true;
  }
  return false;
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === 'PING') {
    sendResponse({ ok: true });
    return true;
  }
  if (message.type === 'HANDLE_SYNC') {
    chrome.storage.local.set({ lastSync: message.payload }).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
  return false;
});
